effect.shader:
const float PI = 3.14159265;
void main() {
    vec4 o = texture(inputImg, acScreenNorm);
    int n = clamp(int(count), 1, 20);
    float a = angle * PI / 180.0;
    vec2 d = vec2(cos(a), sin(a));
    d.x /= max(acAspect, 1e-4);

    vec4 soma = o;
    float peso = 1.0;
    float w = 1.0;
    for (int i = 1; i <= 20; i++) {
        if (i > n) break;
        w *= decay;
        vec2 uv = acScreenNorm - d * deslocamento * float(i);
        soma += texture(inputImg, uv) * w;
        peso += w;
    }
    fragColor = soma / peso;
}
